#!/usr/bin/env bash
# Builds the workspace before the agent starts. claude plugin eval runs it
# only under --scaffold, with the empty workspace as the working directory.
set -euo pipefail
printf '%s' '' | base64 -d > text_utils.py
printf '%s' '' | base64 -d > test_text_utils.py
git init -q 2>/dev/null || true
git add -A 2>/dev/null || true
git -c user.email=e@e -c user.name=e commit -qm 'wip: slugify done, truncate_words still todo' 2>/dev/null || true
